\begin{theorem}[Optimal quadratic approximation with exact parameters]
\label{p1:thm:main}
Fix \(C>0\). For every \(\varepsilon>0\), there are positive
constants \(c_{C,\varepsilon}\), \(C_{C,\varepsilon}\) and a threshold
\(N_0(C,\varepsilon)\) such that, for all \(N\ge N_0\) and every
\(L\) satisfying \eqref{p1:eq:critical},
\begin{equation}
 c_{C,\varepsilon}N^{-4/3-\varepsilon}
 \le \left\|\Law(Z_N)-Q_{\mu_N,\alpha_N}\right\|_1
 \le C_{C,\varepsilon}N^{-4/3+\varepsilon}.
 \label{p1:eq:main}
\end{equation}
Moreover,
\(\mu_N-\lambda_N=O_{C,\varepsilon}(N^{-1+\varepsilon})\),
and \(Q_{\mu_N,\alpha_N}\) is a probability measure for all
sufficiently large \(N\), uniformly in the same band.
\end{theorem}

\begin{corollary}[Exact Poisson total variation scale]
\label{p1:cor:tv}
For every \(\varepsilon>0\), uniformly under \eqref{p1:eq:critical},
\begin{equation}
 \TV(\Law(Z_N),\Pi_{\lambda_N})
 =\frac{\alpha_N}{4}\|\Pi_{\lambda_N}*\Delta^{*2}\|_1
       +O_{C,\varepsilon}(N^{-1+\varepsilon}).
 \label{p1:eq:tv-main}
\end{equation}
Consequently,
\begin{equation}
 \TV(\Law(Z_N),\Pi_{\lambda_N})
 \sim\frac{r+2}{72\,2^{r/3}}\lambda_N^{5/3}
       \|\Pi_{\lambda_N}*\Delta^{*2}\|_1\,L N^{-2/3}.
 \label{p1:eq:tv-equiv}
\end{equation}
With \(\Pi_{\mu_N}\) as the reference, the first formula holds with
\(\mu_N\) in the difference norm and error
\(O_{C,\varepsilon}(N^{-4/3+\varepsilon})\); the equivalent is
unchanged.
\end{corollary}

\begin{proposition}[Centered Bernoulli expansion]
\label{p1:alg:centred}
For every \(N\),
\begin{equation}
 \Law(Z_N)=\sum_{I\subseteq\mathcal I_N}
       c(I)\Delta^{*|I|}*\mathop{*}_{x\notin I}b_x .
 \label{p1:alg:centred-identity}
\end{equation}
The complementary convolution products are deterministic probabilities.
The terms of sizes zero and two are
\[
 \mathop{*}_{x}b_x+
 \sum_{|e|=2}c(e)\Delta^{*2}*\mathop{*}_{x\notin e}b_x.
\]
Terms of size one vanish.
\end{proposition}

\begin{lemma}[Full-support Fourier formula]
\label{p1:alg:fourier}
For nonempty \(I\subseteq\mathcal I_N\),
\begin{equation}
 c(I)=\Bigl(\prod_{x\in I}p_x\Bigr)
   \sum_{\substack{s_x\in S_x\setminus\{0\}\ (x\in I)\\
                         \sum_xs_x=0}}
                 \prod_{x\in I}\eta_x(s_x).
 \label{p1:alg:fourier-identity}
\end{equation}
Consequently,
\[
 |c(I)|\le\Bigl(\prod_{x\in I}p_x\Bigr)(2^{\rho_{\mathrm{rel}}(I)}-1)
           \le\Bigl(\prod_{x\in I}p_x\Bigr)2^{\rho_{\mathrm{rel}}(I)}.
\]
If \(c(I)\ne0\), there is a relative relation meeting
every block of \(I\).
\end{lemma}

\begin{lemma}[A common homogeneous envelope]
\label{p2:homogeneous:envelope}
For a nonempty family $I\subseteq I_N$ of original windows, set
\[
 q_0(I)=2^{-\dim(\sum_{x\in I}S_x)},\qquad
 w(I)=\Bigl(\prod_{x\in I}p_x\Bigr)2^{\rho_{\mathrm{rel}}(I)}.
\]
Then
\begin{equation}
 q_0(I)=2^{\rho_{\mathrm{rel}}(I)}\prod_{x\in I}2^{-d_x},
 \qquad w(I),\ q(I),\ |c(I)|\le q_0(I).
 \label{p2:homogeneous:domination}
\end{equation}
These assertions allow locally inconsistent start prescriptions and
zero marginals. In the critical band, for all sufficiently large $N$,
\begin{equation}
 q_0(I)\le 2^{|I|}p^{|I|}2^{\rho_{\mathrm{rel}}(I)}.
 \label{p2:homogeneous:nominal}
\end{equation}
\end{lemma}

\begin{lemma}[Compatible-nullity majorant]
\label{p1:alg:compatible}
For every \(I\subseteq\mathcal I_N\),
\begin{equation}
 |c(I)|\le 2^{|I|}\Bigl(\prod_{x\in I}p_x\Bigr)2^{\rho_*(I)},\qquad
 \rho_*(I)\le\rho_{\mathrm{rel}}(I).
 \label{p1:alg:compatible-bound}
\end{equation}
Equality holds in the second inequality when \(q(I)>0\).
\end{lemma}

\begin{lemma}[Existence, uniqueness, and factorization]
\label{p1:alg:components}
Every finite family \(I\) has a unique finest direct
partition \(\mathcal P(I)\). For it,
\begin{equation}
 q(I)=\prod_{C\in\mathcal P(I)}q(C),\qquad
 c(I)=\prod_{C\in\mathcal P(I)}c(C),\qquad
 \rho_{\mathrm{rel}}(I)=\sum_{C\in\mathcal P(I)}\rho_{\mathrm{rel}}(C).
 \label{p1:alg:factorization}
\end{equation}
\end{lemma}

\begin{theorem}[Complete pair profile]\label{p1:arith:pairs}
The sums below are over ordered separated pairs in $I_N$:
\begin{align}
 \sum_{|x-y|>L}(2^{\rho(x,y)}-1)
 &=\frac N3\{U_{2,3}(L)+U_{3,4}(L)\}
      +O_{C,\varepsilon}(N^{6/5+\varepsilon}),\label{p1:arith:positiveprofile}\\
 \sum_{|x-y|>L}(\eta(x,y)2^{\rho(x,y)}-1)
 &=\frac N3\{S_{2,3}(L)+S_{3,4}(L)\}
      +O_{C,\varepsilon}(N^{6/5+\varepsilon}).\label{p1:arith:signedprofile}
\end{align}
Writing $\mu_N=\E Z_N$ and $\alpha_N=\operatorname{Var}(Z_N)-\mu_N$, one has
\begin{equation}\label{p1:arith:cumulantexpansion}
 \alpha_N=\frac{\lambda_N^2}{3N}\{S_{2,3}(L)+S_{3,4}(L)\}
            +O_{C,\varepsilon}(N^{-4/5+\varepsilon}).
\end{equation}
Thus, with $r_3=L\bmod3$,
\begin{equation}\label{p1:arith:leadingphase}
 \alpha_N\sim
 \frac{r_3+2}{18\,2^{r_3/3}}\lambda_N^{5/3}L N^{-2/3}.
\end{equation}
After the entire first-channel term is removed, the next term is
\begin{equation}\label{p1:arith:secondphase}
 \alpha_N-\frac{\lambda_N^2}{3N}S_{2,3}(L)
 \sim\frac{r_4+3}{24\,2^{r_4/4}}\lambda_N^{7/4}L N^{-3/4},
 \qquad r_4=L\bmod4.
\end{equation}
\end{theorem}

\begin{corollary}[An explicit probability reference]
\label{p1:cor:explicit}
For every \(\varepsilon>0\), uniformly in the critical band,
\begin{equation}
 \left\|\Law(Z_N)-\Pi_{\lambda_N}
       -\frac{\widehat\alpha_N}{2}
          \Pi_{\lambda_N}*\Delta^{*2}\right\|_1
       \ll_{C,\varepsilon}N^{-4/5+\varepsilon}.
 \label{p1:eq:explicit-law}
\end{equation}
For all sufficiently large \(N\), the reference
\(Q_{\lambda_N,\widehat\alpha_N}\) is a probability measure.
Its mass at \(k\ge0\) is
\begin{equation}
 e^{-\lambda_N}\frac{\lambda_N^k}{k!}
 \left[
  1+\frac{\widehat\alpha_N}{2}
       \left\{\frac{k(k-1)}{\lambda_N^2}
                    -\frac{2k}{\lambda_N}+1\right\}
 \right].
 \label{p1:eq:explicit-masses}
\end{equation}
All parameters in this reference are determined by \(N,L\).
\end{corollary}

\begin{theorem}[Optimal power of the third factorial cumulant]
\label{p13:third:main}
For each fixed critical band $C>0$, there is a constant $c_C>0$ such
that, for all sufficiently large $N$,
\begin{equation}
 c_C N^{-41/30}\leq\kappa_{3,N}
              \ll_{C,\varepsilon}N^{-41/30+\varepsilon}
              \qquad(\varepsilon>0).
 \label{p13:third:two-sided}
\end{equation}
Both bounds are unconditional.  Thus $41/30$ is the optimal power
exponent for this factorial cumulant.  The theorem does not assert an
asymptotic equivalent or identify a logarithmic factor for the full
cumulant.
\end{theorem}

\begin{corollary}[Absolute third-order activity]
\label{p13:third:activity}
For every $\varepsilon>0$,
\begin{equation}
 A_3:=\sum_{|T|=3}|c(T)|
            \ll_{C,\varepsilon}N^{-41/30+\varepsilon}.
 \label{p13:third:absolute}
\end{equation}
\end{corollary}

\begin{lemma}[Expansion at the first excluded prefix]
\label{p1:stop:polynomial}
Let $(u_x)_{x\in G}$ belong to a commutative unital algebra.
Then, as a polynomial identity,
\begin{equation}
 \prod_{x\in G}(1+t u_x)
 =\sum_{I\in\mathscr D}t^{|I|}\prod_{x\in I}u_x
  +\sum_{I\in\partial\mathscr D}
       t^{|I|}\prod_{x\in I}u_x
       \prod_{\substack{y\in G\\y>\max I}}(1+t u_y).
 \label{p1:stop:polynomial-identity}
\end{equation}
\end{lemma}

\begin{proposition}[A positive remainder kernel]
\label{p1:stop:measure}
For arbitrary dependence among the indicators,
\begin{align}
 \Law Z-T_{\mathscr D}
   &=\sum_{I\in\partial\mathscr D}\Delta^{*|I|}*\nu_I,
       \label{p1:stop:measure-identity}\\
 \nu_I
   &=\E\left[
        \left(\prod_{x\in I}J_x\right)
        \delta_{\sum_{y>\max I}J_y}
        \right].
       \notag
\end{align}
The measure $\nu_I$ is positive and has mass $q(I)$.  Consequently,
\begin{equation}
 \|\Law Z-T_{\mathscr D}\|_1
       \le \sum_{I\in\partial\mathscr D}2^{|I|}q(I).
 \label{p1:stop:norm}
\end{equation}
\end{proposition}

\begin{lemma}[Conversion with heterogeneous marginals]
\label{p13:transfer:conversion}
Let $s_j=\sum_i p_i^j$, $C_2=\sum_{|e|=2}c(e)$, and
$\alpha=2C_2-s_2$. If $\mu\leq M$ and $p_*\leq1/4$, then
\begin{equation}
 \|B_2-Q_{\mu,\alpha}\|_1
 \leq C_M\{s_3+s_2^2+A_2(s_2+p_*)\}.
 \label{p13:transfer:conversion-bound}
\end{equation}
For the present model this is $O_{C,\varepsilon}(N^{-5/3+\varepsilon})$.
\end{lemma}

\begin{theorem}[Finite transfer to the complete law]
\label{p13:transfer:finite}
Fix $1<\beta\leq4/3$. Suppose that, for each of the fixed integers
$3\leq r\leq256$ and every $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{|I|=r,\ I\text{ connected}\\\rho_*(I)\leq2L}}
                   |c(I)|\ll_{r,C,\varepsilon}N^{-\beta+\varepsilon}.
 \label{p13:transfer:finite-hypothesis}
\end{equation}
Then
\begin{equation}
 \|\Law(Z_N)-Q_{\mu_N,\alpha_N}\|_1
                  \ll_{C,\varepsilon}N^{-\beta+\varepsilon}.
 \label{p13:transfer:finite-conclusion}
\end{equation}
Only these $254$ fixed orders are assumed in
\eqref{p13:transfer:finite-hypothesis}; the larger orders are supplied
by Proposition~\ref{p13:transfer:uniform-tail}.
\end{theorem}

\begin{theorem}[Reconstruction from triple activity]
\label{p13:transfer:reconstruction}
With the exact mean and second factorial cumulant,
\begin{equation}
 \|\Law(Z_N)-Q_{\mu_N,\alpha_N}\|_1
       \ll_{C,\varepsilon}N^\varepsilon A_3+N^{-4/3+\varepsilon}.
 \label{p13:transfer:reconstruction-bound}
\end{equation}
In particular the arithmetic triple estimate gives the upper bound
$O_{C,\varepsilon}(N^{-4/3+\varepsilon})$ for the full model.
\end{theorem}

\begin{lemma}[The fourth factorial cumulant]
\label{p13:lower:quartic}
For every fixed critical band and every $\varepsilon>0$,
\begin{equation}
 \kappa_4=24K_4+O_{C,\varepsilon}(N^{-5/3+\varepsilon}),\qquad
 K_4=K_4^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}).
 \label{p13:lower:quartic-identities}
\end{equation}
Consequently
\begin{equation}
 \kappa_4+3\alpha^2
 =3\alpha^2+24K_4^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}).
 \label{p13:lower:positive-quartic}
\end{equation}
\end{lemma}

\begin{theorem}[Optimal power for the exact quadratic reference]
\label{p13:lower:optimal}
For every $C>0$ and $\varepsilon>0$, there are
$c_{C,\varepsilon}>0$ and $N_0(C,\varepsilon)$ such that
\begin{equation}
 \|\Law(Z_N)-Q_{\mu_N,\alpha_N}\|_1
 \geq c_{C,\varepsilon}N^{-4/3-\varepsilon}
 \label{p13:lower:norm}
\end{equation}
whenever $N\geq N_0$ and $|L-\log_2N|\leq C$.
Together with Theorem~\ref{p13:transfer:reconstruction} and the triple
activity bound, this identifies the optimal power as $4/3$.
It does not assert an asymptotic constant or a logarithmic factor for
the remainder.
\end{theorem}

\begin{lemma}[Positivity of the quadratic Poisson correction]
\label{p1:close:positivity}
Let $\mu>0$, $\alpha\in\mathbb R$, and
$\theta=\mu-\lfloor\mu\rfloor$.  Then $Q_{\mu,\alpha}$ is a
probability measure if and only if
\begin{equation}
 0\le\alpha\le
       \frac{2\mu^2}{\mu+\theta(1-\theta)}.
 \label{p1:close:positivity-range}
\end{equation}
Its masses are
\begin{equation}
 Q_{\mu,\alpha}\{k\}
 =e^{-\mu}\frac{\mu^k}{k!}
   \left[1+\frac{\alpha}{2\mu^2}
                    \bigl((k-\mu)^2-k\bigr)\right],
 \qquad k\ge0.
 \label{p1:close:charlier-masses}
\end{equation}
\end{lemma}

\begin{corollary}[Every fixed polynomial weight]
\label{p13:optimal:weighted}
For every fixed integer \(m\ge0\) and \(\varepsilon>0\),
\begin{equation}
 \sum_{k\ge0}(1+k)^m
   \left|\P(Z_N=k)-Q_{\mu_N,\alpha_N}\{k\}\right|
       \ll_{C,m,\varepsilon}N^{-4/3+\varepsilon}.
 \label{p13:optimal:weighted-bound}
\end{equation}
For every fixed \(r\ge2\), consequently,
\begin{equation}
 \E(Z_N)_r
 =\mu_N^r+\binom r2\mu_N^{r-2}\alpha_N
           +O_{C,r,\varepsilon}(N^{-4/3+\varepsilon}).
 \label{p13:optimal:moments}
\end{equation}
The equalities for \(r=0,1,2\) hold without a remainder
when the right side is interpreted in its natural form.
\end{corollary}

\begin{proposition}[The quantized mean bias]
\label{p13:optimal:nominal}
Let \(\eta_x\) indicate one-window compatibility and put
\(h_x=L-\dim S_x\). Then
\begin{equation}
 \mu_N-\lambda_N=pM_{N,L},\qquad
 M_{N,L}=\sum_{x\in I_N}(\eta_x2^{h_x}-1)\in\Z.
 \label{p13:optimal:integer-mean}
\end{equation}
Thus either \(\mu_N=\lambda_N\) or
\(|\mu_N-\lambda_N|\ge p\asymp_C N^{-1}\).
Keeping the same exact \(\alpha_N\), one has
\[
 \|\Law Z_N-Q_{\lambda_N,\alpha_N}\|_1
       \ll_{C,\varepsilon}N^{-1+\varepsilon}.
\]
On every sufficiently large admissible pair \((N,L)\)
for which \(M_{N,L}\ne0\),
\begin{equation}
 \|\Law Z_N-Q_{\lambda_N,\alpha_N}\|_1
       \asymp_C|\mu_N-\lambda_N|.
 \label{p13:optimal:nominal-distance}
\end{equation}
No assertion that \(M_{N,L}\ne0\) at infinitely many
scales is included.
\end{proposition}

\begin{theorem}[The optimal error of every fixed height truncation]
\label{p13:channels:hierarchy}
Fix $h\geq3$ and $C>0$, and write $b=h+1$ and $r=L\bmod b$.
For every $\varepsilon>0$, uniformly in the critical band,
\begin{align}
 \alpha_N-\widehat\alpha_N^{(\leq h)}
  &=\frac{\lambda_N^2}{N}T_b(L)
       +O_{h,C,\varepsilon}(N^{-b/(b+1)+\varepsilon}),
       \label{p13:channels:cumulant-remainder}\\
 \Law(Z_N)-Q_{\lambda_N,\widehat\alpha_N^{(\leq h)}}
  &=\frac{\lambda_N^2T_b(L)}{2N}\Pi_{\lambda_N}*\Delta^{*2}
       +O_{\ell^1,h,C,\varepsilon}(N^{-b/(b+1)+\varepsilon}).
       \label{p13:channels:law-remainder}
\end{align}
Define the positive number
\begin{equation}
 c_b(r)=\frac{b+r-1}{b^2\,2^{r/b}}
       \sum_{\substack{b/2<a<b\\(a,b)=1}}
                    \frac{(2a-b)(b-a)}a .
 \label{p13:channels:phase-constant}
\end{equation}
The reference is a probability measure for all sufficiently large $N$, and
\begin{equation}
 \TV\bigl(\Law(Z_N),Q_{\lambda_N,\widehat\alpha_N^{(\leq h)}}\bigr)
 \sim \frac{c_b(r)}4\lambda_N^{2-1/b}
       \|\Pi_{\lambda_N}*\Delta^{*2}\|_1\,
       L N^{-1+1/b}.
 \label{p13:channels:tv-equivalent}
\end{equation}
The ratio tends to one uniformly over the critical band with the displayed
moving parameters retained.  Thus the optimal power exponent of this
specified reference is $h/(h+1)$.
\end{theorem}

\begin{lemma}[Weighted nonaligned pairs]
\label{p13:channels:weighted-nonaligned}
For every $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{x,y\in G_N,\ |x-y|>L\\(x,y)\ {\rm nonaligned}}}
             (2^{\rho(x,y)}-1)
       \ll_{C,\varepsilon}N^{1+\varepsilon}.
 \label{p13:channels:nonaligned-weight}
\end{equation}
Consequently the sum of the absolute covariances on these pairs is
$O_{C,\varepsilon}(N^{-1+\varepsilon})$.
\end{lemma}

\begin{corollary}[The error of the two-channel reference]
\label{p13:channels:height-five}
Write $L=5q+r$, $0\leq r<5$, and, for $q\geq1$, set
\begin{equation}
 \begin{split}
 M_5(N,L)&=\frac{\lambda_N^2}{N}
             \left\{\frac2{15}S_{3,5}(L)+\frac3{10}S_{4,5}(L)\right\}\\
 &=\frac{\lambda_N^2}{30N}
   \left\{2^{q-1}\bigl[17(r+4)q+13r^2+87r+620\bigr]
                              -113L-127\right\}.
 \end{split}
 \label{p13:channels:M5}
\end{equation}
Then
\begin{align}
 \Law(Z_N)-Q_{\lambda_N,\widehat\alpha_N}
   &=\frac{M_5(N,L)}2\Pi_{\lambda_N}*\Delta^{*2}
                +O_{\ell^1,C,\varepsilon}(N^{-5/6+\varepsilon}),
                \label{p13:channels:two-channel-law}\\
 \TV(\Law(Z_N),Q_{\lambda_N,\widehat\alpha_N})
   &\sim\frac{17(r+4)}{1200\,2^{r/5}}\lambda_N^{9/5}
       \|\Pi_{\lambda_N}*\Delta^{*2}\|_1\,L N^{-4/5}.
                \label{p13:channels:two-channel-tv}
\end{align}
The four-channel coefficient is
$\widehat\alpha_N^{(\leq5)}=\widehat\alpha_N+M_5(N,L)$.
Its reference has optimal exponent $5/6$, with leading phase constant
$c_6(r)=(r+5)/(45\,2^{r/6})$, where now $r=L\bmod6$.
\end{corollary}

\begin{lemma}[Local and global defect counts]\label{p1:arith:defects}
Suppose $B\asymp\log N$ and $H\asymp B$, with fixed comparison constants.
Any interval of diameter $O(B)$ in $[cN,CN]$ contains
$O(B/\log B)$ $H$-defective integers.  Moreover
\begin{align}
 \#\{n\leq CN:K_H(n)=1\}&\leq N^{1/2+o(1)},\label{p1:arith:onedfect}\\
 \#\{x\in I_N:V_x\text{ contains two }H\text{-defective integers}\}
   &\leq N^{o(1)}.\label{p1:arith:twodefect}
\end{align}
All statements remain valid after fixed dilations and translations of the
intervals.
\end{lemma}

\begin{lemma}[Two small odd kernels]\label{p1:arith:twokernel}
Uniformly for $B\asymp\log N$, fixed $0<\beta<1$, and $\varepsilon>0$,
\[
 G_2(N,N^\beta):=
 \#\{x\in I_N:\#\{n\in V_x:K_B(n)\leq N^\beta\}\geq2\}
 \ll_{\beta,C,\varepsilon}N^{\max(\beta,7/12)+\varepsilon}.
\]
For $7/12\leq\beta<1$ this exponent is sharp in the sense
$G_2(N,N^\beta)=N^{\beta+o(1)}$.
\end{lemma}

\begin{lemma}[The dense weighted sector]\label{p1:arith:dense}
For every fixed $\eta,\varepsilon>0$,
\[
 \sum_{\substack{x,y\in I_N,\ |x-y|>L\\
        (x,y)\ {\rm nonaligned},\ c(x,y)\geq\eta B}}
       (2^{\rho(x,y)}-1)
 \ll_{C,\eta,\varepsilon}N^{1+\varepsilon}.
\]
The same bound holds for the full value kernel, without block-parity rows.
\end{lemma}

\begin{proposition}[Regular set]\label{p1:arith:core}
Let
\[
 G_N=\{x\in I_N:\dim S_x=L\},\qquad Z_N^\circ=\sum_{x\in G_N}J_x.
\]
Then $|I_N\setminus G_N|=N^{o(1)}$, and
\begin{equation}\label{p1:arith:coretransfer}
 d_{\rm TV}(\Law(Z_N),\Law(Z_N^\circ))+
 |\E Z_N-\lambda|+|\E Z_N^\circ-\lambda|
 \ll_C N^{-1+o(1)}.
\end{equation}
More generally, for every deterministic $A\subset I_N$ and every choice of
affine targets on its windows,
\begin{equation}\label{p1:arith:marginalsum}
 \sum_{x\in A}|\P(A_xX=b_x)-p|\leq pN^{o(1)}.
\end{equation}
If the fixed moments of $Z_N$ are uniformly bounded, then, for every fixed
integer $j\geq1$ and every $\varepsilon>0$,
\begin{equation}\label{p1:arith:momenttransfer}
 \big|\E Z_N^j-\E(Z_N^\circ)^j\big|
 \ll_{C,j,\varepsilon}N^{-1+\varepsilon}.
\end{equation}
In particular the second factorial cumulants have the same transfer bound.
\end{proposition}

\begin{proposition}[Support and residual mass]\label{p1:arith:hosts}
For every $\varepsilon>0$,
\begin{align}
 \#\{(x,y)\in I_N^2:|x-y|>L,\ \rho(x,y)>0\}
   &\ll_{C,\varepsilon}N^{1+\varepsilon},
       \label{p1:arith:hostbound}\\
 \sum_{\substack{x,y\in I_N,\ |x-y|>L\\(x,y)\ {\rm nonaligned}}}
       (2^{\rho(x,y)}-1)
   &\ll_{C,\varepsilon}N^{1+\varepsilon}.
       \label{p1:arith:nonaligned}
\end{align}
\end{proposition}

\begin{corollary}[The pair input for the expansion]\label{p1:arith:edgefamily}
One has $|\mathcal E_N|=O_C(NB)$ and, for an edge in channel $a:b$,
\[
 \rho(e)\leq L/b+O(1),\qquad q_e\leq p^2 2^{L/b+O(1)}.
\]
Moreover,
\begin{align}
 2\beta_N&=\alpha_N+O_{C,\varepsilon}(N^{-4/5+\varepsilon}),
    \label{p1:arith:edgemass}\\
 \sum_{\substack{x,y\in G_N,\ x\ne y\\\{x,y\}\notin\mathcal E_N}}
   |\E[(J_x-p)(J_y-p)]|
 &\ll_{C,\varepsilon}N^{-4/5+\varepsilon}+B/N.
    \label{p1:arith:badpairs}
\end{align}
In particular $\beta_N\asymp_C LN^{-2/3}$.
\end{corollary}

\begin{proposition}[Large rank loss after fixed sources]
\label{p1:fixed:targets}
For every fixed \(s\ge1\) and \(\eta,\varepsilon>0\),
\begin{equation}
 \sup_{x_1,\ldots,x_s\ {\rm distinct}}
 \#\{z\in I_N\setminus\{x_1,\ldots,x_s\}:
                   \delta_z\ge\eta L\}
       \ll_{s,C,\eta,\varepsilon}N^\varepsilon .
 \label{p1:fixed:targets-bound}
\end{equation}
The sources may be dependent or overlapping.
\end{proposition}

\begin{proposition}[Conditional sums and propagation]
\label{p1:fixed:propagation}
For every fixed \(s\ge1\) and \(\varepsilon>0\), uniformly
over compatible prescribed affine events at \(s\) distinct
sources,
\begin{equation}
 \sum_{z\notin\{x_1,\ldots,x_s\}}
 \P(J_z=1\mid J_{x_1}=\cdots=J_{x_s}=1)
       \ll_{s,C,\varepsilon}N^\varepsilon .
 \label{p1:fixed:conditional}
\end{equation}
This assertion also holds when the affine prescriptions
are replaced by homogeneous ones. If a family of ordered
\(s\)-tuples has total positive joint mass \(W_{s,N}\),
the mass of its extensions to ordered distinct \(r\)-tuples,
for fixed \(r\ge s\), is
\begin{equation}
 W_{s\to r,N}\ll_{r,C,\varepsilon}N^\varepsilon W_{s,N}.
 \label{p1:fixed:propagate}
\end{equation}
In particular, the mass of fixed \(r\)-tuples containing
a local defect or a compatible contact is
\(O_{r,C,\varepsilon}(N^{-1+\varepsilon})\).
\end{proposition}

\begin{theorem}[Fixed factorial moments]
\label{p1:fixed:moments}
For every fixed integer \(r\ge2\) and every
\(\varepsilon>0\),
\begin{equation}
 \E(Z_N)_r
   =\mu_N^r+\binom r2\mu_N^{r-2}\alpha_N
       +O_{r,C,\varepsilon}(N^{-4/5+\varepsilon}).
 \label{p1:fixed:moment-expansion}
\end{equation}
Equivalently, one may use \(\lambda_N\) and
\(a_N=\E(Z_N)_2-\lambda_N^2\).
All fixed ordinary moments are bounded. More precisely,
with \(T_r(u)=\E[\Pois(u)^r]\),
\begin{equation}
 \E Z_N^r
    =T_r(\mu_N)+\frac{\alpha_N}{2}T_r''(\mu_N)
       +O_{r,C,\varepsilon}(N^{-4/5+\varepsilon}).
 \label{p1:fixed:ordinary}
\end{equation}
For every fixed \(r\ge3\), the \(r\)-th factorial
cumulant is \(O_{r,C,\varepsilon}(N^{-4/5+\varepsilon})\).
\end{theorem}

\begin{proposition}[Fixed primitive mass after pair compression]
\label{p1:fixed:compressed}
Fix a channel \(a:b\in\{2:3,3:4\}\), and put
\(\kappa_b=2-1/b\). All original starts lie in \(G_N\) and are
distinct and pairwise separated. For every fixed \(r\ge3\) and
\(\varepsilon>0\), the total
homogeneous mass of primitive families consisting of
one exactly compressed pair in this channel and
\(r-1\) further original windows is
\begin{equation}
 O_{r,C,\varepsilon}
       (N^{-\kappa_b+\varepsilon}).
 \label{p1:fixed:compressed-bound}
\end{equation}
For a compressed geometric good pair and just one further original
window with positive relative rank loss, the mass is
\(O_{C,\varepsilon}(N^{-41/30+\varepsilon})\) in either channel.
The affine positive masses satisfy the same bounds.
\end{proposition}

\begin{proposition}[Uniform moments for short split products]
\label{p13:short:moments}
For every fixed even integer \(v\ge2\), with the preceding notation,
\begin{equation}
 \E\left|\sum_{n\asymp N}f(P_A(n))\right|^v
 \le N^{v/2+c[v(v-1)+2]\log2+o(1)}.
 \label{p13:short:moment-bound}
\end{equation}
In particular, for each fixed \(v\) and \(\varepsilon>0\),
one may choose \(c>0\) so that the \(L^v\) norm is
\(O(N^{1/2+\varepsilon})\), uniformly in all the indicated
motifs. The summation interval may have any fixed comparable
length and positive height.
\end{proposition}

\begin{theorem}[Conditional full-support count]
\label{p13:half:conditional}
Fix \(r\ge1\), \(s\ge0\), \(D>0\), and \(\varepsilon>0\).
Let \(V_{\rm old}\) be the space generated by all values
in \(s\) fixed source blocks. Uniformly in those sources,
the number of lists of distinct new centres \(z_1,\ldots,z_r\)
such that
\begin{equation}
 u_i\in S_{z_i}\setminus\{0\}\quad(1\le i\le r),
 \qquad \sum_i u_i\in V_{\rm old}
 \label{p13:half:condition}
\end{equation}
for some \(u_i\), is \(O_{r,s,D,C,\varepsilon}(N^{r/2+\varepsilon})\).
The \(u_i\) need not remain nonzero modulo \(V_{\rm old}\).
The source blocks may overlap or be dependent.
\end{theorem}

\begin{lemma}[Two small kernels]
\label{p13:half:small-kernels}
For every fixed \(q>0\) and \(\varepsilon>0\),
\(\#\mathcal X_q\ll_{q,D,C,\varepsilon}N^{q+\varepsilon}\).
\end{lemma}

\begin{corollary}[Dense nonaligned pairs]
\label{p13:conf:dense-pairs}
For fixed \(\eta,\varepsilon>0\), nonaligned pairs
with \(d_{xy}\ge\eta B\) have \(O(N^\varepsilon)\)
hosts.
\end{corollary}

\begin{theorem}[A short basis with a controlled loss of dimension]
\label{p13:rig:short-basis}
For every fixed $a\in(0,1)$ there is a subspace $\mathcal K_a$
of complete relations of the pair, with injective projections
onto each physical block and onto the common square class,
such that
\begin{equation}
 \dim\mathcal K_a\ge d_{xy}-\frac23B\log(1/a)
                    -O_{a,C}\!\left(\frac B{\sqrt{\log B}}\right).
 \label{p13:rig:short-dimension}
\end{equation}
It has a basis whose vectors have total physical support at most
\begin{equation}
                    O_{a,C}\!\left(
                         \frac{B^a\log B}{\log\log B}\right).
 \label{p13:rig:short-support}
\end{equation}
Every nonzero vector selects a nonempty even set in each block
and has nonzero common square class.  Neither compatibility nor
nonalignment is assumed.
\end{theorem}

\begin{proposition}[Integer fibres in the offset grid]
\label{p13:rig:grid-fibres}
Under the hypotheses of Theorem~\ref{p13:rig:common-curve},
assume both physical projections of $V$ are injective.
Put $D=\deg C_0$, $d_X=\deg_XC_0$, $d_Y=\deg_YC_0$.
For an absolute constant $c$,
\begin{equation}
 \#\{(u,v)\in[-B,B]^2\cap\Z^2:C_0(-u,-v)=0\}
       \ge\max(d_X,d_Y)(t-1-cD^2).
 \label{p13:rig:grid-count}
\end{equation}
A negative right side may be replaced by zero.
\end{proposition}

\begin{theorem}[A uniform nonaligned rank bound]
\label{p13:rig:nonaligned}
For every fixed critical band,
\begin{equation}
 \limsup_{N\to\infty}\ 
 \sup_{\substack{x,y\in I_N\\x,y\ {\rm nonaligned}}}
             \frac{d_{xy}}B
       \le\frac23\log2<\frac12.
 \label{p13:rig:nonaligned-bound}
\end{equation}
Compatibility of the two events is not needed.
\end{theorem}

\begin{proposition}[Rank on a known alignment]
\label{p13:rig:aligned}
Suppose $bx-ay=h$, where $(a,b)=1$, $1\le a,b\le B^3$,
and $|h|\le(a+b)B$.  For every fixed $\tau\in(0,1)$,
\begin{equation}
 d_{xy}\le\frac B{\max(a,b)}+\frac23B\log(1/\tau)
                    +O_{\tau,C}(B/\sqrt{\log B}).
 \label{p13:rig:aligned-quantitative}
\end{equation}
For distinct compatible centres this implies, uniformly
over aligned pairs,
$d_{xy}\le B/2+o_C(B)$.  If such a pair has an alignment
with $a=b=1$, then $d_{xy}=o_C(B)$.
\end{proposition}

\begin{corollary}[Triple rank and maximum joint probability]
\label{p13:rig:triple}
Every compatible triple $T$ of distinct centres in the
fixed critical band satisfies
\begin{equation}
                 \rho_{\rm rel}(T)\le\frac32L+o_C(L).
 \label{p13:rig:triple-nullity}
\end{equation}
If any of its pairs is nonaligned, the stronger bound
$\rho_{\rm rel}(T)\le(1+(2/3)\log2)L+o_C(L)$ holds.
In particular, with $q(T)=\E\prod_{x\in T}J_x$,
\begin{equation}
                  \max_{\substack{T\subset I_N\\|T|=3}}q(T)
                            \le N^{-3/2+o_C(1)}.
 \label{p13:rig:max-triple}
\end{equation}
\end{corollary}

\begin{theorem}[Absolute activity of incompatible triples]
\label{p13:activity:incompatible}
For every \(\varepsilon>0\),
\[
 \sum_{\substack{T\subseteq\mathcal I_N,\ |T|=3\\q(T)=0}}
           |c(T)|\ll_{C,\varepsilon}N^{-3/2+\varepsilon}.
\]
Both signs of the centered coefficient are included.
\end{theorem}

\begin{proposition}[The third cumulant and the positive activity]
\label{p13:activity:kappa3}
Every compatible triple has \(c(T)\ge0\), and
\begin{equation}
 \kappa_{3,N}=6K_3^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}),
 \qquad
 A_3=K_3^++O_{C,\varepsilon}(N^{-3/2+\varepsilon}).
 \label{p13:activity:kappa-comparison}
\end{equation}
In the second equality the difference \(A_3-K_3^+\)
is nonnegative.
\end{proposition}

\begin{lemma}[A sharp rational overlap inequality]
\label{p13:third:rational-rank}
For all integers $u<v<w<2u$ with $(u,v,w)=1$,
\begin{equation}
 D(u,v,w)\leq\frac{19}{30}.
 \label{p13:third:1930}
\end{equation}
Equality holds for $(u,v,w)=(10,12,15)$.
This is an inequality for the canonical coincidence geometry; arithmetic
relations among the distinct normalized values require a separate bound.
\end{lemma}

\begin{proposition}[Triples meeting finitely many aligned channels]
\label{p13:third:aligned-family}
Fix a finite set $\mathcal F$ of reduced interior channels $a:b$, with
$b\geq3$ and $b/2<a<b$, before $N$.  Then
\begin{equation}
 \sum_{\substack{|T|=3,\ T\ {\rm connected},\ q(T)>0\\
            \text{some pair of }T\text{ is aligned in }\mathcal F}}q(T)
       \ll_{\mathcal F,C,\varepsilon}N^{-41/30+\varepsilon}.
 \label{p13:third:aligned-family-bound}
\end{equation}
The sum allows irregular admissible windows, bad normalization of the
source pair, and contacts at distance exactly $L$.
\end{proposition}

\begin{corollary}[Strong aligned pairs]
\label{p13:third:aligned}
For every fixed $\theta>0$ and every $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{|T|=3,\ T\ {\rm connected},\ q(T)>0\\
        \exists\{x,y\}\subset T\ {\rm aligned}:\ d_{xy}\geq\theta B}}
             q(T)\ll_{C,\theta,\varepsilon}N^{-41/30+\varepsilon}.
 \label{p13:third:strong-aligned-bound}
\end{equation}
\end{corollary}

\begin{proposition}[The rational lower bound]
\label{p13:third:lower}
For all sufficiently large $N$ in the critical band,
\begin{equation}
 K_3^+:=\sum_{\substack{|T|=3,\ T\ {\rm connected}\\q(T)>0}}c(T)
                  \gg_C N^{-41/30}.
 \label{p13:third:K3-lower}
\end{equation}
In particular $\kappa_{3,N}\geq c_C N^{-41/30}$ for a suitable
$c_C>0$.
\end{proposition}

\begin{proposition}[Positive Palm cost of a fixed channel]
\label{p1:arith:palm}
\label{p1:arith:palm-all-targets}
Fix a reduced interior channel $a:b$, with $0<a<b<2a$, and an integer
$D\ge6b$. Choose an integer private-prime threshold with
$6bB\le H\le DB$.
Let $\mathcal E_{a,b}$ be its compatible dependent good edges, write $J_e=\prod_{x\in e}J_x$ and
$q_e=\P(J_e=1)$, and put $\beta_{a,b}=\sum_{e\in\mathcal E_{a,b}}q_e$.
For a deterministic set of targets $G\subseteq I_N$, define
\begin{align*}
 M_{\mathrm{ex}}(G)
   &=\sum_{e\in\mathcal E_{a,b}}\sum_{z\in G\setminus e}
       \bigl(q(e\cup\{z\})-q_ep_z\bigr)_+,\\
 M_{\mathrm{nom}}(G)
   &=\sum_{e\in\mathcal E_{a,b}}q_e\sum_{z\in G\setminus e}
       \bigl(\P(J_z=1\mid J_e=1)-p\bigr)_+.
\end{align*}
For every fixed critical band and $\varepsilon>0$, uniformly in $G$
and in the stated range of $H$, for all sufficiently large $N$,
\begin{equation}
 \begin{split}
 &\beta_{a,b}>0,\qquad
 M_{\mathrm{ex}}(G)+M_{\mathrm{nom}}(G)
     \ll_{a,b,C,D,\varepsilon}N^{-41/30+\varepsilon},\\
 &\frac{M_{\mathrm{ex}}(G)+M_{\mathrm{nom}}(G)}{\beta_{a,b}}
     \ll_{a,b,C,D,\varepsilon}N^{-11/30-1/b+\varepsilon}.
 \end{split}
 \label{p2:palm:all-targets-bound}
\end{equation}
No regularity condition is imposed on the target windows.
\end{proposition}

\begin{lemma}[Counting a small truncated squarefree kernel]
\label{p1:core:rankin}
For fixed $1/2<\sigma<1$, fixed $C_1>0$, and $T\ge1$,
\begin{equation}
 \#\{v\le C_1N:K_Y(v)\le T\}
 \ll_{\sigma,C_1}N^\sigma T^{1-\sigma}
       \exp(C_\sigma Y^{1-\sigma}).
 \label{p1:core:rankin-bound}
\end{equation}
\end{lemma}

\begin{lemma}[Counting moderate certificates]
\label{p1:core:moderate}
Let $\mathcal U_r$ be the ordered lists of $r$ distinct original windows having
such a certificate, and set
$m=\lceil 2\log(3N)/\log Y\rceil$. Then
\begin{equation}
 |\mathcal U_r|
 \le36rB^4 2^{r-1}N^rT^{-2}(rB)^m.
 \label{p1:core:moderate-count}
\end{equation}
For every fixed $u>0$,
\begin{equation}
 \sum_{r\ge1}\frac{(up)^r}{r!}|\mathcal U_r|
 \le N^{-2\beta+4/A_0+o(1)}.
 \label{p1:core:moderate-baseline}
\end{equation}
\end{lemma}

\begin{lemma}[Incoming and outgoing saturation degrees]
\label{p1:core:degrees}
Uniformly in the fixed vertex,
\begin{equation}
 \deg^+(x),\deg^-(x)\le N^{2/A_0+o(1)},
 \qquad \Delta(\Gamma)\le N^{2/A_0+o(1)}.
 \label{p1:core:degree-bound}
\end{equation}
\end{lemma}

\begin{lemma}[A generating function with marked isolated vertices]
\label{p1:core:generator}
Let a simple graph have $n$ vertices, maximum degree $\Delta$ and
$M$ marked vertices. If $\mathcal F$ consists of the vertex sets
whose induced isolated vertices are all marked, then, for $z\ge0$,
\begin{equation}
 \sum_{D\in\mathcal F}z^{|D|}
 \le\exp\left\{Mz+nz\bigl((1+z)^\Delta-1\bigr)\right\}.
 \label{p1:core:generator-bound}
\end{equation}
More generally, for nonnegative vertex weights $w_v$ and marked set
$\mathcal M$,
\[
 \sum_{D\in\mathcal F}\prod_{v\in D}w_v
 \le \exp\left\{\sum_{v\in\mathcal M}w_v+
 \sum_vw_v\left(\prod_{u\sim v}(1+w_u)-1\right)\right\}.
\]
\end{lemma}

\begin{lemma}[Conditional dense pair estimate]
\label{p13:transfer:dense-targets}
Fix a number $s$ of source windows and an effective subspace $W$ of
their value space. Suppose $S_y\cap W=S_z\cap W=0$, and write
\[
 d=\dim W+\dim S_y+\dim S_z-\dim(W+S_y+S_z).
\]
For every fixed $\eta,\varepsilon>0$ there exists a fixed $\theta>0$
such that, uniformly in the sources and $W$,
\begin{equation}
 \sum_{\substack{y\ne z,\ y,z\text{ outside the sources}\\
             d\geq\eta L\\
             (y,z)\text{ nonaligned or }\dim(S_y\cap S_z)\leq\theta L}}
         p_yp_z2^d\ll_{s,C,\eta,\varepsilon}N^{-1+\varepsilon}.
 \label{p13:transfer:dense-target-bound}
\end{equation}
In particular the hypothesis on the pair is satisfied when $S_y,S_z$
are direct. For a primitive family of fixed size $r\geq3$, with a
prescribed collection of $r-2$ sources having at most $N^{a+\varepsilon}$
possibilities, its dense homogeneous mass is at most
\begin{equation}
 \sum_{\rho\geq\eta L}\Bigl(\prod_{i\in I}p_i\Bigr)2^{\rho(I)}
          \ll N^{-(r-1)+a+\varepsilon}.
 \label{p13:transfer:restricted-dense}
\end{equation}
\end{lemma}

\begin{lemma}[A dense compressed target]
\label{p13:transfer:compressed-target}
For fixed sources and a fixed channel of good pairs, the number of
compressed centers $X$ for which
$\dim(S(U_X)\cap W)\geq\eta L$ is $O_{s,C,\eta,\varepsilon}(N^\varepsilon)$.
\end{lemma}

\begin{lemma}[Several small kernels in one window]
\label{p13:transfer:small-kernels}
Fix $A>2$, $0<b,u<1$, and an integer $m$ with $m(1-b)>1$.
For $Y=(\log N)^A$, the number of windows containing $m$ distinct
values with $K_Y(n)\leq N^b$ and $a_Y(n)^2\leq N^u$ is
\begin{equation}
 \ll N^{\max(1-1/A,(1+u)/2)+\varepsilon}.
 \label{p13:transfer:small-kernels-bound}
\end{equation}
Also, with the previously fixed cutoff $H=C_DB$, the set
$\mathcal X_q$ of windows containing distinct $n_1,n_2$
with $K_H(n_1)K_H(n_2)\leq N^q$ has cardinality
$O(N^{q+\varepsilon})$, for fixed $q\geq0$.
\end{lemma}

\begin{lemma}[Uniform independent deficit]
\label{p13:transfer:independent-deficit}
For fixed $s,u,C$ and every $\varepsilon>0$,
\begin{equation}
 E_W(u)\ll_{s,u,C,\varepsilon}N^{-1/2+\varepsilon},
 \label{p13:transfer:independent-bound}
\end{equation}
uniformly in the sources and $W$. The sum includes all cardinalities.
\end{lemma}

\begin{lemma}[A fixed number of extensions of a pair]
\label{p13:transfer:fixed-deficit}
For every fixed $k\geq1$,
\begin{equation}
 \sum_{|e|=2}|c(e)|
 \sum_{\substack{U\cap e=\varnothing,\ |U|=k\\
                  S_e,(S_z)_{z\in U}\text{ not direct}}}
                  \prod_{z\in U}p_z
 \ll_{k,C,\varepsilon}N^{-3/2+\varepsilon},
 \qquad S_e=\sum_{i\in e}S_i.
 \label{p13:transfer:fixed-pair-bound}
\end{equation}
\end{lemma}

\begin{lemma}[Independent full-support tails]
\label{p13:transfer:independent-tail}
Fix a critical band, fixed bounds on the block widths and centre ranges,
a weight $v>0$, and an exponent $a<2$.
There exist a fixed integer $s\ge3$ and a scale threshold such that,
for every $N$ above that threshold,
\begin{equation}
 \sum_{\substack{|F|\ge s\\F\text{ has a full-support relation}}}
                  \prod_{x\in F}(vp_x)\le N^{-a}.
 \label{p13:transfer:tail-independent}
\end{equation}
The same conclusion holds with one block of any of the fixed compressed
types, weighted by $vp$, and with the remaining factors $vp_x$.
The cutoff and threshold depend only on the fixed parameters, not on
$N,L$ or the chosen blocks. In particular the cutoff is fixed before
any later exponent margin.
\end{lemma}

\begin{proposition}[The pair deficit over all cardinalities]
\label{p13:transfer:pair-deficit}
For fixed $u>0$ and every $\varepsilon>0$,
\begin{equation}
 D_2(u)\ll_{u,C,\varepsilon}N^{-3/2+\varepsilon}.
 \label{p13:transfer:pair-deficit-bound}
\end{equation}
In particular it is smaller than the $N^{-4/3}$ scale required below.
\end{proposition}

\begin{proposition}[Reduction of connected activities]
\label{p13:transfer:fixed-activities}
For every fixed $r\geq4$ and every $\varepsilon>0$,
\begin{equation}
 \sum_{\substack{|I|=r\\I\text{ connected}}}|c(I)|
 \ll_{r,C,\varepsilon}N^\varepsilon A_3+N^{-4/3+\varepsilon}.
 \label{p13:transfer:fixed-activity-bound}
\end{equation}
The incompatible part, for every fixed $r\geq4$, is
$O_{r,C,\varepsilon}(N^{-3/2+\varepsilon})$.
\end{proposition}

\begin{lemma}[Certificate budgets with several anchors]
\label{p13:transfer:anchor-budgets}
Choose an even integer $t\geq2$, $A_0>1$, $0<b<1$, and
$1/2<\sigma<1$ with $A_0(1-\sigma)<1$. Put
\[
 \delta=(1-b)(1-\sigma),\qquad \theta=t/A_0.
\]
Suppose each unmarked block in a family has a relation selecting at
least $t$ values in that block; the relation may depend on the block.
Mark a block when some value has odd kernel above
$Y=(\log N)^{A_0}$ at most $N^b$.
Under any fixed independent weight per block, the moderate certificates
have total mass
\begin{equation}
 N^{-tb+2t/A_0+o(1)}.
 \label{p13:transfer:moderate-budget}
\end{equation}
If $\theta+\delta<1$, the saturated families of size at least $s$
have total independent mass
\begin{equation}
 N^{-s\delta/2+o(1)}.
 \label{p13:transfer:saturated-budget}
\end{equation}
\end{lemma}

\begin{proposition}[Uniform connected and primitive tails]
\label{p13:transfer:uniform-tail}
For fixed $w>0$, every $\varepsilon>0$, and every $K_N=o(L)$,
\begin{align}
 \sum_{\substack{I\text{ connected},\ 256<|I|\leq K_N\\
                         \rho_*(I)\leq2L}}
              w^{|I|}|c(I)|&\ll N^{-4/3+\varepsilon},
                    \label{p13:transfer:connected-tail}\\
 \sum_{\substack{P\text{ primitive}\\|P|>256}}
              w^{|P|}|c(P)|&\ll N^{-4/3+\varepsilon}.
                    \label{p13:transfer:primitive-tail}
\end{align}
The second sum includes all cardinalities. Here
$\rho_*(I)=\max\{\rho(A):A\subseteq I,\ q(A)>0\}$.
\end{proposition}

\begin{proposition}[A uniform weighted count of full supports]
\label{p1:uniform:full-support}
For a fixed critical band, fixed $u>0$ and $\varepsilon>0$, uniformly
in deterministic $G\subseteq G_N$ and integers $s\ge2$,
\begin{equation}
 \sum_{r=s}^{|G|}\frac{u^r}{r!}
     \sum_{\boldsymbol x\in\mathcal H_{r,N}(G)}p^r
       \ll_{u,C,\varepsilon}N^{-\min\{s/2,2\}+\varepsilon}.
 \label{p2:uniform:full-support-bound}
\end{equation}
The scale threshold and implicit constant are independent of $s$ and $G$.
Empty sums are zero.
\end{proposition}

\begin{proposition}[Norms of Poisson differences]
\label{p1:discussion:charlier-norm}
For $\mu>0$, put $\pi_\mu(k)=e^{-\mu}\mu^k/k!$ when $k\ge0$
and $\pi_\mu(k)=0$ when $k<0$.  Define
\[
 u_\pm=\mu+\frac12\pm\frac{\sqrt{4\mu+1}}2,\qquad
 a=\lfloor u_-\rfloor+1,\qquad b=\lceil u_+\rceil-1.
\]
Then
\begin{equation}
 \|\Pi_\mu*\Delta^{*2}\|_1
 =2\bigl\{\pi_\mu(a-1)-\pi_\mu(a-2)
             +\pi_\mu(b-1)-\pi_\mu(b)\bigr\}.
 \label{p1:discussion:finite-norm}
\end{equation}
More generally, for every integer $r\ge0$,
\begin{equation}
 \|\Pi_\mu*\Delta^{*r}\|_1
       \le\min\left\{2^r,\frac{\sqrt{r!}}{\mu^{r/2}}\right\}.
 \label{p1:discussion:general-norm}
\end{equation}
In particular,
\begin{equation}
 \|\Pi_2*\Delta^{*2}\|_1=\frac{10}{3e^2},
 \qquad \mathcal C(2)=\frac{5}{6e^2}.
 \label{p1:discussion:lambda-two}
\end{equation}
\end{proposition}
